-- =============================================-- Author:		<Jose Roman>-- Create date: <13-07-2018>-- Description:	<Se consulta la cantidad de materiales que hicieron falta de recibir al momento de cerrar el pedido>-- =============================================IF EXISTS (SELECT 1 FROM dbo.sysobjects WHERE name = 'MM_SP_ConsultaValidacionReaperturaPedido')    DROP PROCEDURE MM_SP_ConsultaValidacionReaperturaPedidoGOCREATE PROCEDURE MM_SP_ConsultaValidacionReaperturaPedido --1632	@IdPedido INT,	/*--------------------parametros contrato  --------------------*/    @IdContrato    INT = null,    @IdUsuario     INT = null,    @FechaRegistro DATETIME = null	/*-------------------------------------------------------------*/ASBEGIN	SELECT 		pod.IdSolicitudPedidoDetalle,		(pd.Cantidad - SUM(ISNULL(apd.Cantidad, 0))) AS CantidadFaltanteAlCierre,		pd.IdPedidoDetalle	FROM dbo.MM_Pedido p	INNER JOIN	 dbo.MM_PedidoDetalle pd 		ON p.IdPedido = pd.IdPedido	INNER JOIN dbo.MM_PeticionOfertaDetalle pod 		ON pd.IdPeticionOfertaDetalle = pod.IdPeticionOfertaDetalle	LEFT JOIN	MM_AceptacionPedido	AP		ON	p.IdPedido	=	AP.IdPedido		AND ISNULL(AP.IdEliminado,0)	=	0	LEFT JOIN dbo.MM_AceptacionPedidoDetalle apd 		ON AP.IdAceptacionPedido	=	apd.IdAceptacionPedido		AND	apd.IdPedidoDetalle = pd.IdPedidoDetalle	WHERE 		p.idpedido = @IdPedido		AND ISNULL(apd.IdEstatusEliminado, 0) = 0	GROUP BY pd.IdPedidoDetalle, pd.Cantidad, pod.IdSolicitudPedidoDetalleEND